<script setup lang="ts">
import WalletCustomerProofHistory from '../proof/WalletCustomerProofHistory.vue'
import WalletProofHistory from '../proof/WalletProofHistory.vue'
import WalletPointsReversalAction from '../components/WalletPointsReversalAction.vue'
import {computed} from 'vue'
import {useRoute} from 'vue-router'
import {useI18n} from 'vue-i18n'
import {useWalletRecord} from '../useWalletRecord'
import {dateTime} from '../format'
import {transactionEventLabel} from '../transactions/eventLabel'
import {customerWalletPath,staffWalletPath} from '../navigation'
import {safeTransactionReturn} from '../transactions/query'
import type {TransactionDetail} from '../transactions/types'
import WalletTransactionRow from '../transactions/WalletTransactionRow.vue'
const route=useRoute(),{t}=useI18n(),customer=route.meta.walletWorkspace==='customer',store=computed(()=>String(route.params.storeId)),path=computed(()=>`/transactions/${encodeURIComponent(String(route.params.sourceType??(route.params.billId?'bill':route.params.topupId?'topup':'refund')))}/${encodeURIComponent(String(route.params.transactionId??route.params.billId??route.params.topupId??route.params.refundId))}`)
const {record,ready,busy,error}=useWalletRecord<TransactionDetail>(store,path,customer)
const back=computed(()=>safeTransactionReturn(route.query.returnTo??(['points','topup'].includes(String(route.params.sourceType))?(customer?customerWalletPath:staffWalletPath)(store.value,'transactions')+'?category='+route.params.sourceType:undefined),store.value,customer))
</script>
<template><h2>{{t('wallet.transactions.title')}}</h2><p v-if="error" class="wallet-error" role="alert">{{error}}</p><p v-if="!ready&&busy" role="status">{{t('wallet.loading')}}</p><template v-if="record"><WalletTransactionRow :row="record.transaction" :customer="customer" :return-to="back" /><section class="wallet-card"><dl class="wallet-detail-fields"><template v-for="[key,value] in [['created',record.transaction.createdAt],['posted',record.transaction.postedAt],['occurred',record.transaction.occurredAt]]" :key="key??''"><dt>{{t(`wallet.transactions.${key}`)}}</dt><dd>{{value?dateTime(value,record.transaction.timeZone):'—'}}</dd></template><dt v-if="record.transaction.actorName">{{t('wallet.transactions.actor')}}</dt><dd v-if="record.transaction.actorName">{{record.transaction.actorName}}</dd></dl><p v-if="record.transaction.summary">{{record.transaction.summary}}</p></section><RouterLink v-if="customer&&record.transaction.sourceType==='topup'&&record.transaction.status==='pending'" class="wallet-secondary-link" :to="{path:customerWalletPath(store,'topup'),query:{topupId:record.transaction.id}}">{{t('wallet.topup')}}</RouterLink><WalletCustomerProofHistory v-if="customer&&['topup','bill'].includes(record.transaction.sourceType)" :store="store" :source-type="record.transaction.sourceType" :source-id="record.transaction.id" /><WalletProofHistory v-if="!customer&&['topup','bill'].includes(record.transaction.sourceType)" :store="store" :source-type="record.transaction.sourceType" :source-id="record.transaction.id" /><WalletPointsReversalAction v-if="!customer&&record.transaction.sourceType==='points'" :store="store" :detail="record" :return-to="back" /><h3 v-if="record.related.length">{{t('wallet.transactions.related')}}</h3><WalletTransactionRow v-for="row in record.related" :key="row.sourceType+row.id" :row="row" :customer="customer" :return-to="back" /><h3 v-if="record.events.length">{{t('wallet.transactions.events')}}</h3><p v-for="(event,index) in record.events" :key="index">{{transactionEventLabel(event,record.transaction.status,t)}} · {{event.occurredAt||event.at?dateTime((event.occurredAt??event.at)!,record.transaction.timeZone):'—'}} {{event.summary}}</p></template><RouterLink :to="back" class="wallet-secondary-link">{{t('wallet.ui.back')}}</RouterLink></template>
